#![cfg(all(windows,feature="producer-test-fixture"))]
use std::{os::windows::process::CommandExt,path::Path,process::Command};

#[test] fn both_sdks_retry_offline_then_commit_to_same_gateway() {
    let mut random=[0u8;16];getrandom::fill(&mut random).unwrap();let suffix:String=random.iter().map(|b|format!("{b:02x}")).collect();let base=Path::new(env!("CARGO_MANIFEST_DIR")).join(format!("MindTrailSdk-{suffix}"));std::fs::create_dir(&base).unwrap();let root=base.join("state");
    let node=std::env::var_os("MINDTRAIL_TEST_NODE").expect("MINDTRAIL_TEST_NODE required");let python=std::env::var_os("MINDTRAIL_TEST_PYTHON").expect("MINDTRAIL_TEST_PYTHON required");let js=std::env::var_os("MINDTRAIL_SDK_JS").expect("MINDTRAIL_SDK_JS required");let project=std::env::var_os("MINDTRAIL_SDK_ROOT").expect("MINDTRAIL_SDK_ROOT required");let project=std::path::PathBuf::from(project);let producer=env!("CARGO_BIN_EXE_mindtrail-producer");
    let run=|phase:&str| {let output=Command::new(&node).arg(project.join("tests/fixtures/sdk_real.mjs")).arg(&js).arg(producer).arg(phase).env("MINDTRAIL_TEST_ROOT",&root).creation_flags(0x08000000).output().unwrap();assert!(output.status.success(),"node SDK: {}",String::from_utf8_lossy(&output.stderr));let output=Command::new(&python).arg(project.join("tests/fixtures/sdk_real.py")).arg(producer).arg(project.join("sdk/python")).arg(phase).env("MINDTRAIL_TEST_ROOT",&root).creation_flags(0x08000000).output().unwrap();assert!(output.status.success(),"Python SDK: {}",String::from_utf8_lossy(&output.stderr));};
    run("offline");let gateway=mindtrail_lib::gateway::lifecycle::Gateway::start(&root).unwrap();run("online");
    let discovery:serde_json::Value=serde_json::from_slice(&std::fs::read(root.join("endpoint.json")).unwrap()).unwrap();let port=discovery["port"].as_u64().unwrap() as u16;let token=discovery["token"].as_str().unwrap();
    let curl_event=serde_json::json!({"v":1,"session":"sdk-curl","seq":1,"ts":"2024-01-01T00:00:00Z","type":"task.start","payload":{"title":"Curl","goal":"G","project":"P"}});let batch=base.join("batch.json");std::fs::write(&batch,serde_json::to_vec(&vec![curl_event.clone()]).unwrap()).unwrap();let pwsh=std::env::var_os("MINDTRAIL_TEST_PWSH").expect("MINDTRAIL_TEST_PWSH required");
    for (accepted,duplicates) in [(1,0),(0,1)] {let output=Command::new(&pwsh).args(["-NoProfile","-File"]).arg(project.join("sdk/examples/submit-events.ps1")).arg("-DiscoveryPath").arg(root.join("endpoint.json")).arg("-BatchPath").arg(&batch).arg("-ScratchDirectory").arg(&base).creation_flags(0x08000000).output().unwrap();assert!(output.status.success(),"curl example: {}",String::from_utf8_lossy(&output.stderr));assert!(!output.stdout.windows(token.len()).any(|w|w==token.as_bytes()));assert!(!output.stderr.windows(token.len()).any(|w|w==token.as_bytes()));let receipt:serde_json::Value=serde_json::from_slice(&output.stdout).unwrap();assert_eq!(receipt,serde_json::json!({"accepted":accepted,"duplicates":duplicates,"last_seq":1}));}
    for session in ["sdk-node","sdk-python","sdk-curl"] {use std::io::{Read,Write};let mut stream=std::net::TcpStream::connect(("127.0.0.1",port)).unwrap();stream.set_read_timeout(Some(std::time::Duration::from_secs(3))).unwrap();write!(stream,"GET /v1/sessions/{session}/events HTTP/1.1\r\nHost: 127.0.0.1:{port}\r\nAuthorization: Bearer {token}\r\nConnection: close\r\n\r\n").unwrap();let mut response=String::new();stream.read_to_string(&mut response).unwrap();let (header,body)=response.split_once("\r\n\r\n").unwrap();assert!(header.starts_with("HTTP/1.1 200"));let value:serde_json::Value=serde_json::from_str(body).unwrap();assert_eq!(value["events"].as_array().unwrap().len(),1);assert_eq!(value["events"][0]["session"],session);if session=="sdk-curl" {assert_eq!(value["events"][0],curl_event);}}
    gateway.shutdown().unwrap();
}
